--- terraform/main.tf
terraform {
  required_version = ">= 1.5"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

# The cluster is owned by the platform repository. This module reads it only.
data "aws_eks_cluster" "existing" {
  name = var.cluster_name
}


--- terraform/variables.tf
variable "cluster_name" {
  description = "Name of the externally managed EKS cluster."
  type        = string
}

variable "private_subnet_ids" {
  description = "Private subnet IDs supplied by the platform."
  type        = list(string)
}

variable "permissions_boundary_arn" {
  description = "Required IAM permissions boundary for roles created here."
  type        = string
}


--- terraform/iam.tf
# This role is used only by the dedicated ARC runner node group. It does not
# grant this module ownership of the existing EKS cluster or legacy resources.
data "aws_iam_policy_document" "runner_node_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "runner_node" {
  name                 = "arc-runner-node"
  assume_role_policy   = data.aws_iam_policy_document.runner_node_assume_role.json
  permissions_boundary = var.permissions_boundary_arn
}

resource "aws_iam_role_policy_attachment" "runner_node_managed" {
  for_each = toset([
    "arn:aws:iam::aws:policy/AmazonEKSWorkerNodePolicy",
    "arn:aws:iam::aws:policy/AmazonEC2ContainerRegistryPullOnly",
    "arn:aws:iam::aws:policy/AmazonEKS_CNI_Policy",
  ])

  role       = aws_iam_role.runner_node.name
  policy_arn = each.value
}

--- terraform/runners.tf
# The platform owns image selection; this module only consumes the approved
# parameter value in the dedicated runner launch template below.
data "aws_ssm_parameter" "runner_ami" {
  name = "/platform/arc/runner-ami"
}

resource "aws_launch_template" "runner_node" {
  name_prefix = "arc-runner-node-"

  image_id      = data.aws_ssm_parameter.runner_ami.value
  instance_type = "m7i.large"

  # Require IMDSv2 for nodes that will execute CI workloads.
  metadata_options {
    http_tokens = "required"
  }
}

resource "aws_eks_node_group" "runner" {
  cluster_name    = data.aws_eks_cluster.existing.name
  node_group_name = "arc-runner"
  node_role_arn   = aws_iam_role.runner_node.arn
  subnet_ids      = var.private_subnet_ids
  capacity_type   = "ON_DEMAND"

  scaling_config {
    min_size     = 2
    desired_size = 2
    max_size     = 6
  }

  labels = {
    workload = "arc-runner"
  }

  taint {
    key    = "dedicated"
    value  = "arc-runner"
    effect = "NO_SCHEDULE"
  }

  launch_template {
    id      = aws_launch_template.runner_node.id
    version = aws_launch_template.runner_node.latest_version
  }

  # EKS must not attempt to create nodes before their role permissions exist.
  depends_on = [aws_iam_role_policy_attachment.runner_node_managed]
}

